import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c

    if total_opp_c == 0:
        return 'D'

    recent = history[-8:]
    opp_c = sum(1 for a, b in recent if b == 'C')
    opp_d = len(recent) - opp_c

    if n >= 97:
        if total_opp_d <= 3:
            return 'C'
        if total_opp_c * 100 >= n * 60:
            return 'D'
        return 'D' if opp_last == 'C' else 'C'

    if n >= 90:
        if total_opp_d <= 2:
            return 'C'
        if opp_c >= 6:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'D' if opp_last == 'D' else 'C'

    if total_opp_d == 0:
        if n > 15 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if opp_last == 'D':
        if opp_c >= 7:
            return 'C'
        if opp_d >= 5:
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if opp_d >= 3 and opp_c == 0:
        return 'D'

    if total_opp_c * 100 >= n * 80 and n > 25:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    return 'C'
